+// Importing till sales from CSV (ticket,soldAt,dishId,qty). Each dish sold
+// uses `qty` recipe portions. A ticket already imported is skipped. The whole
+// file is imported or nothing is.
+import { AppError } from "../errors.js";
+import { t } from "../i18n/messages.js";
+import { getDish } from "../domain/menu.js";
+import { cook } from "../domain/recipes.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports sales; returns { tickets, dishes } counts or throws bad_request naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const bad = (where, reason) => new AppError("bad_request", { reason: `${where}: ${reason}` });
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+    const dishId = Number(r.dishId);
+    const qty = Number(r.qty);
+    if (!r.ticket) throw bad(where, "ticket is required");
+    if (!/^\d{4}-\d{2}-\d{2}T[\d:.]+(Z|[+-]\d{2}:\d{2})$/.test(r.soldAt) || Number.isNaN(Date.parse(r.soldAt)))
+      throw bad(where, "bad soldAt");
+    if (!Number.isInteger(dishId) || !(store.data.dishes ?? []).some((d) => d.id === dishId)) throw bad(where, "unknown dish");
+    if (!Number.isInteger(qty) || qty < 1) throw bad(where, "bad qty");
+    return { where, ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty };
+  });
+
+  store.data.sales ??= [];
+  const known = new Set(store.data.sales.map((s) => s.ticket));
+  const fresh = new Set();
+  let dishes = 0;
+  const backup = structuredClone({ batches: store.data.batches, movements: store.data.movements, seq: store.data.seq, sales: store.data.sales });
+  try {
+    for (const c of clean) {
+      if (known.has(c.ticket)) continue;
+      try {
+        cook(store, getDish(store, c.dishId).recipeId, c.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+      } catch (e) {
+        if (e instanceof AppError && e.code !== "bad_request") throw bad(c.where, t(e.code, "en", e.params).replace(/\.$/, ""));
+        throw e;
+      }
+      store.data.sales.push({ ticket: c.ticket, soldAt: c.soldAt, dishId: c.dishId, qty: c.qty });
+      fresh.add(c.ticket);
+      dishes += c.qty;
+    }
+  } catch (e) {
+    Object.assign(store.data, backup);
+    throw e;
+  }
+  return { tickets: fresh.size, dishes };
+}
